typedef long long ll;

static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int N;
    ll M;
    if (scanf("%d %lld", &N, &M) != 2) return 0;

    ll *A = (ll *)malloc(sizeof(ll) * N);
    for (int i = 0; i < N; i++) scanf("%lld", &A[i]);

    qsort(A, N, sizeof(ll), cmp_ll);

    ll *val = (ll *)malloc(sizeof(ll) * N);
    ll *cnt = (ll *)malloc(sizeof(ll) * N);
    int K = 0;

    for (int i = 0; i < N; ) {
        int j = i + 1;
        while (j < N && A[j] == A[i]) j++;
        val[K] = A[i];
        cnt[K] = j - i;
        K++;
        i = j;
    }

    ll ans = 0;

    /* Pair equal values first */
    for (int i = 0; i < K; i++) {
        ans += cnt[i] / 2;
        cnt[i] %= 2;
    }

    /* Collect remaining single cards by residue */
    ll *res = (ll *)malloc(sizeof(ll) * K);
    ll *rcnt = (ll *)malloc(sizeof(ll) * K);
    int R = 0;

    for (int i = 0; i < K; i++) {
        if (cnt[i]) {
            ll r = ((val[i] % M) + M) % M;
            res[R] = r;
            rcnt[R] = 1;
            R++;
        }
    }

    if (R == 0) {
        printf("%lld\n", ans);
        free(A); free(val); free(cnt); free(res); free(rcnt);
        return 0;
    }

    qsort(res, R, sizeof(ll), cmp_ll);

    /* Compress residues */
    ll *u = (ll *)malloc(sizeof(ll) * R);
    ll *c = (ll *)malloc(sizeof(ll) * R);
    int U = 0;
    for (int i = 0; i < R; ) {
        int j = i + 1;
        while (j < R && res[j] == res[i]) j++;
        u[U] = res[i];
        c[U] = j - i;
        U++;
        i = j;
    }

    /* Pair residues r with M-r */
    int l = 0, r = U - 1;
    while (l <= r) {
        if (l == r) {
            ll x = u[l];
            if ((2 * x) % M == 0) ans += c[l] / 2;
            break;
        }
        ll sum = u[l] + u[r];
        if (sum == M) {
            ll add = c[l] < c[r] ? c[l] : c[r];
            ans += add;
            l++;
            r--;
        } else if (sum < M) {
            l++;
        } else {
            r--;
        }
    }

    printf("%lld\n", ans);

    free(A);
    free(val);
    free(cnt);
    free(res);
    free(rcnt);
    free(u);
    free(c);

    return 0;
}

