public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        long M = fs.nextLong();

        HashMap<Long, Long> count = new HashMap<>();
        for (int i = 0; i < N; i++) {
            long a = fs.nextLong();
            long r = ((a % M) + M) % M;
            count.put(r, count.getOrDefault(r, 0L) + 1);
        }

        long ans = 0;
        HashSet<Long> used = new HashSet<>();

        for (Map.Entry<Long, Long> entry : count.entrySet()) {
            long r = entry.getKey();
            if (used.contains(r)) continue;

            long c = count.get(r);

            if (r == 0 || (2 * r == M)) {
                ans += c / 2;
                used.add(r);
            } else {
                long s = (M - r) % M;
                long d = count.getOrDefault(s, 0L);

                if (r == s) {
                    ans += c / 2;
                    used.add(r);
                } else {
                    ans += Math.min(c, d);
                    used.add(r);
                    used.add(s);
                }
            }
        }

        System.out.println(ans);
    }
}

