int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    vector<int> a(N);
    for (int i = 0; i < N; i++) {
        cin >> a[i];
    }

    // Group by value first
    unordered_map<int, int> valueCount;
    for (int x : a) {
        valueCount[x]++;
    }

    // Group by residue modulo M
    vector<vector<int>> groups(M);
    for (auto &p : valueCount) {
        int val = p.first;
        int cnt = p.second;
        groups[val % M].push_back(cnt);
    }

    int pairs = 0;

    // First, pair within same value: for each residue group, pair same values
    for (int r = 0; r < M; r++) {
        for (int &cnt : groups[r]) {
            pairs += cnt / 2;
            cnt %= 2;
        }
    }

    // Now handle pairing across residues
    auto process = [&](int r1, int r2) {
        if (r1 == r2) {
            int total = 0;
            for (int cnt : groups[r1]) total += cnt;
            pairs += total / 2;
            // set all to 0 since used
            groups[r1].clear();
        } else {
            int i = 0, j = 0;
            while (i < (int)groups[r1].size() && j < (int)groups[r2].size()) {
                int take = min(groups[r1][i], groups[r2][j]);
                pairs += take;
                groups[r1][i] -= take;
                groups[r2][j] -= take;
                if (groups[r1][i] == 0) i++;
                if (groups[r2][j] == 0) j++;
            }
        }
    };

    // Pair r with M-r
    for (int r = 1; r < M; r++) {
        if (r > M - r) break; // avoid double counting
        if (r == M - r) {
            // M even, r == M/2
            process(r, r);
        } else {
            process(r, M - r);
        }
    }
    // Handle r=0 separately
    process(0, 0);

    cout << pairs << "\n";

    return 0;
}

