int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    // Group by remainder, and inside each remainder count equal values.
    vector<map<long long, long long>> mp(M);
    for (int i = 0; i < N; ++i) {
        long long a;
        cin >> a;
        mp[a % M][a]++;
    }

    long long ans = 0;

    // Handle remainder 0 separately: only same-remainder pairing matters.
    {
        long long cnt = 0;
        for (auto &[v, c] : mp[0]) cnt += c;
        ans += cnt / 2;
    }

    // If M is even, handle remainder M/2 separately.
    if (M % 2 == 0) {
        long long cnt = 0;
        for (auto &[v, c] : mp[M / 2]) cnt += c;
        ans += cnt / 2;
    }

    // Handle pairs of remainders r and M-r.
    for (int r = 1; r < (M + 1) / 2; ++r) {
        int s = M - r;

        // First, pair equal values inside each side as much as possible.
        long long paired_same = 0;
        long long rem_r = 0, rem_s = 0;

        for (auto &[v, c] : mp[r]) {
            paired_same += c / 2;
            rem_r += c % 2;
        }
        for (auto &[v, c] : mp[s]) {
            paired_same += c / 2;
            rem_s += c % 2;
        }

        // Then pair remaining singles across complementary remainders.
        ans += paired_same + min(rem_r, rem_s);
    }

    cout << ans << '\n';
    return 0;
}
